customCSS:
.t, .history { color: #534c45; }
.join { color: #396847; }
.part, .quit { color: #534c45; }
.kick, .error { color: #a5222f; }
.notice { color: #ac5402; }
.action { color: #6e33ce; }
.mode, .nick, .topic, .server { color: #287980; }
.highlight { color: #3d2b5a; background-color: #e7d2be; border-left: 3px solid #6e33ce; padding-left: 8px; }
.reply { color: #534c45; border-left: 2px solid #2848a9; padding-left: 6px; }
.oper { color: #f6f2ee; background-color: #ac5402; }
.reactions { color: #2848a9; background-color: #eee4df; }
.card { background-color: #eee4df; border-color: #534c45; }
.card-title { color: #2848a9; }
.card-desc { color: #534c45; }
.daychange { color: #534c45; border-color: #eee4df; }
